using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpHttpServer;

[McpServerToolType]
public static class GreetingTools
{
    [McpServerTool(Name = "greet"), Description("Greets a user by name.")]
    public static string Greet(string name) => $"Hello, {name}!";
}

using ModelContextProtocol.Server;

namespace McpHttpServer;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "app_settings",
        MimeType = "application/json", Title = "Application Settings")]
    public static string GetAppSettings()
    {
        return """
        {
            "appName": "McpHttpServer",
            "version": "1.0.0",
            "features": {
                "darkMode": true,
                "maxRetries": 3,
                "timeout": 30
            }
        }
        """;
    }

    [McpServerResource(UriTemplate = "config://app/environment/{envName}", Name = "environment_config",
        MimeType = "application/json", Title = "Environment Configuration")]
    public static string GetEnvironmentConfig(string envName)
    {
        return envName.ToLowerInvariant() switch
        {
            "production" => """{"logLevel": "Warning", "debugMode": false, "replicas": 3}""",
            "staging" => """{"logLevel": "Information", "debugMode": false, "replicas": 1}""",
            _ => """{"logLevel": "Debug", "debugMode": true, "replicas": 1}"""
        };
    }
}

